alter table staff_shifts add constraint staff_shifts_shift_code_check CHECK (((shift_code IS NULL) OR ((shift_code >= 1) AND (shift_code <= 3))));
alter table parking_invoices add constraint parking_invoices_entity_type_check CHECK ((entity_type = ANY (ARRAY['subscriber'::text, 'reservation'::text, 'rotation'::text, 'hotel_batch'::text, 'stay_change'::text, 'commerce_sale'::text])));
alter table parking_invoices add constraint parking_invoices_entity_type_entity_id_billing_month_key UNIQUE (entity_type, entity_id, billing_month);
alter table parking_invoices add constraint parking_invoices_number_key UNIQUE (number);
alter table parking_cash_movements add constraint parking_cash_movements_amount_eur_check CHECK ((amount_eur >= (0)::numeric));
alter table parking_cash_movements add constraint parking_cash_movements_category_check CHECK ((category = ANY (ARRAY['subscriber'::text, 'stay'::text, 'rotation'::text])));
alter table parking_cash_movements add constraint parking_cash_movements_payment_method_check CHECK ((payment_method = ANY (ARRAY['cash'::text, 'card'::text, 'bank'::text, 'online'::text])));
alter table parking_cash_movements add constraint parking_cash_movements_source_key_key UNIQUE (source_key);
alter table parking_cash_movements add constraint parking_cash_payment_required CHECK (((payment_method IS NOT NULL) OR ((amount_eur = (0)::numeric) AND (category = 'rotation'::text))));
alter table parking_simplified_invoices add constraint parking_simplified_invoices_movement_id_key UNIQUE (movement_id);
alter table parking_simplified_invoices add constraint parking_simplified_invoices_number_key UNIQUE (number);

create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function private.is_staff() returns boolean language sql stable as $$select exists(select 1 from public.staff_profiles where user_id=auth.uid() and active)$$;
create function public.rotation_operator_context() returns jsonb language sql stable as $$select jsonb_build_object('user_id',auth.uid(),'employee_name','QA','role','admin','shift_id',null)$$;
create function private.parking_cash_state(uuid) returns jsonb language sql stable as $$select jsonb_build_object('saved',true,'difference',coalesce(nullif(current_setting('sandbox.difference',true),''),'0')::numeric)$$;
create function public.parking_cashbook(date,integer,uuid) returns jsonb language sql stable as $$select '{}'::jsonb$$;
create function private.stay_price(uuid,integer,timestamptz) returns numeric language sql stable as $$select 20::numeric$$;


alter table public.parking_cash_counts add primary key(shift_id);
create function private.parking_legacy_voucher_balance(p_at timestamptz default clock_timestamp()) returns numeric language sql as $$select 0::numeric$$;
CREATE OR REPLACE FUNCTION private.parking_cash_state_before_vouchers(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.parking_cash_counts;v_open numeric:=0;v_previous_vouchers numeric:=0;v_previous_loose numeric:=0;v_previous_wrapped numeric:=0;v_previous_notes numeric:=0;v_previous_shift uuid;v_cash numeric;v_expenses numeric;v_vouchers numeric;v_withdrawals numeric;v_expected numeric;v_counted numeric;v_entries jsonb;
begin
 select * into c from public.parking_cash_counts where shift_id=p_shift_id;
 if c.shift_id is null then
  select old.loose_coins+old.wrapped_coins+old.banknotes+old.vouchers,old.vouchers,old.loose_coins,old.wrapped_coins,old.banknotes,old.shift_id
  into v_open,v_previous_vouchers,v_previous_loose,v_previous_wrapped,v_previous_notes,v_previous_shift
  from public.parking_cash_counts old join public.staff_shifts s on s.id=old.shift_id
  where s.closed_at is not null and s.id<>p_shift_id and s.opened_at<(select opened_at from public.staff_shifts where id=p_shift_id)
  order by s.closed_at desc limit 1;
 else v_open:=c.opening_balance;end if;
 select coalesce(sum(amount_eur),0) into v_cash from public.parking_cash_movements where shift_id=p_shift_id and payment_method='cash';
 select coalesce(sum(amount_eur) filter(where kind='expense'),0),coalesce(sum(amount_eur) filter(where kind='voucher'),0),coalesce(jsonb_agg(to_jsonb(e) order by created_at),'[]'::jsonb) into v_expenses,v_vouchers,v_entries from public.parking_cash_entries e where shift_id=p_shift_id;
 select coalesce(sum(amount_eur),0) into v_withdrawals from public.parking_cash_withdrawals where shift_id=p_shift_id;
 v_expected:=coalesce(v_open,0)+v_cash-v_expenses-v_withdrawals;
 v_counted:=coalesce(c.loose_coins,v_previous_loose,0)+coalesce(c.wrapped_coins,v_previous_wrapped,0)+coalesce(c.banknotes,v_previous_notes,0)+coalesce(c.vouchers,coalesce(v_previous_vouchers,0)+v_vouchers);
 return jsonb_build_object('saved',c.shift_id is not null,'inherited_from_shift',v_previous_shift,'opening_balance',coalesce(v_open,0),'loose_coins',coalesce(c.loose_coins,v_previous_loose,0),'wrapped_coins',coalesce(c.wrapped_coins,v_previous_wrapped,0),'banknotes',coalesce(c.banknotes,v_previous_notes,0),'vouchers',coalesce(c.vouchers,coalesce(v_previous_vouchers,0)+v_vouchers),'cash_total',coalesce(c.loose_coins,v_previous_loose,0)+coalesce(c.wrapped_coins,v_previous_wrapped,0)+coalesce(c.banknotes,v_previous_notes,0),'counted_total',v_counted,'cash_income',v_cash,'expense_total',v_expenses,'voucher_total',v_vouchers,'withdrawal_total',v_withdrawals,'expected_balance',v_expected,'difference',v_counted-v_expected,'entries',v_entries,'updated_at',c.updated_at);
end $function$

;
